\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{amssymb}

\title{Anchored Fine-Tuning for Low-Resource Text Classification}
\author{J.~Lin and M.~Okafor}
\date{}

\begin{document}
\maketitle

\begin{abstract}
We study fine-tuning of large pretrained language models for text
classification when only a few hundred labeled examples are available. We
propose an anchoring objective that keeps the adapted weights close to
their pretrained initialization, and show that it improves dev-set
accuracy on two low-resource benchmarks.
\end{abstract}

\section{Training Objective}
Let $\theta_0$ denote the pretrained parameters of the encoder and let
$\theta$ denote the parameters being optimized. Given a training set of
$N$ examples over $C$ classes, we minimize the anchored objective
\begin{equation}
\label{eq:anchored}
\mathcal{L}(\theta) \;=\;
-\frac{1}{N} \sum_{i=1}^{N} \sum_{c=1}^{C}
y_{i,c}\, \log \hat{p}_{i,c}(\theta)
\;+\; \lambda\, \lVert \theta - \theta_0 \rVert_2^{2},
\end{equation}
where $y_{i,c}$ is the one-hot label of example $i$, and
$\hat{p}_{i,c}(\theta)$ is the predicted probability that example $i$
belongs to class $c$.

\subsection{Remarks}
The first term of \eqref{eq:anchored} is the average cross-entropy loss
over the training set. The second term penalizes the squared Euclidean
distance between the fine-tuned weights and their pretrained
initialization. The scalar $\lambda > 0$ trades off fit to the labeled
data against proximity to $\theta_0$; we set $\lambda = 0.01$ in all
experiments unless stated otherwise.

\begin{figure}[t]
\centering
\fbox{\rule[-2.2cm]{0pt}{4.4cm}\rule{7.5cm}{0pt}}
\caption{Overview of the anchored fine-tuning pipeline. The encoder starts
from $\theta_0$ and is pulled back toward it by the anchoring term during
optimization.}
\label{fig:pipeline}
\end{figure}

\section{Preliminary Results}
Table~\ref{tab:acc} reports dev-set accuracy on two low-resource
benchmarks, averaged over five random seeds.

\begin{table}[h]
\centering
\begin{tabular}{lcc}
\hline
Method & SST-2 (250 ex.) & CoLA (250 ex.) \\
\hline
Standard fine-tuning & 85.1 & 61.4 \\
Anchored fine-tuning & 87.3 & 64.9 \\
\hline
\end{tabular}
\caption{Dev-set accuracy (\%) with 250 training examples.}
\label{tab:acc}
\end{table}

